import time
import logging
from taf.internal.protocol.tl1.message import (CommandCode, Payload, StagingBlock, Response, Acknowledgment,
                                               DataBlock, InputMessage)


class Command(object):
    def __init__(self, session):
        self._session = session

    @property
    def input_message(self):
        raise NotImplementedError

    def execute(self, wait=0, recv_timeout=5, output_process=None):
        logging.info("sending message:\r\n  '{}'".format(self.input_message))
        self._session.send_message(self.input_message)
        time.sleep(wait)
        output_process = output_process or self.process_response
        return output_process(timeout=recv_timeout)

    def process_response(self, timeout, terminator=';'):
        response_text = self._session.receive_message(message_terminator=terminator,
                                                      msg_sent=self.input_message,
                                                      timeout=timeout)
        logging.info("received output:\r\n'{}'\r\n for message:\r\n '{}'".format(response_text, self.input_message))
        return Response.from_text(response_text, message_terminator=terminator)

    def process_ack(self, timeout):
        response_text = self._session.receive(timeout)
        return Acknowledgment.from_text(response_text)


class ActUser(Command):
    def __init__(self, session, uid, pid, ctag="", tid=""):
        super(ActUser, self).__init__(session)
        self._command_code = CommandCode('ACT', modifiers=['USER', ])
        self._staging_block = StagingBlock(tid=tid, aid_or_uid=uid, ctag=ctag)
        self._payload = Payload(data_blocks=[DataBlock(pid), ])
        self._input_message = InputMessage(command_code=self._command_code,
                                           staging_block=self._staging_block,
                                           payload=self._payload)

    @property
    def input_message(self):
        return self._input_message.text


class CancUser(Command):
    def __init__(self, session, tid="", uid="", ctag="", exit_session=True):
        super(CancUser, self).__init__(session)
        self._command_code = CommandCode('CANC', modifiers=['USER', ])
        self._staging_block = StagingBlock(tid=tid, aid_or_uid=uid, ctag=ctag)
        exitsess = 'y' if exit_session else 'n'
        self._payload = Payload(data_blocks=[DataBlock(exitsess=exitsess), ])
        self._input_message = InputMessage(command_code=self._command_code,
                                           staging_block=self._staging_block,
                                           payload=self._payload)

    @property
    def input_message(self):
        return self._input_message.text


class OPRLinkFlap(Command):
    def __init__(self,
                 session,
                 ports,
                 tid="",
                 ctag="",
                 lowperiod=None,
                 highperiod=None,
                 period=None,
                 frequency=None,
                 repeat=None,
                 duration=None):
        super(OPRLinkFlap, self).__init__(session)
        data_block = DataBlock(lowperiod=lowperiod,
                               highperiod=highperiod,
                               period=period,
                               frequency=frequency,
                               repeat=repeat,
                               duration=duration,
                               ports=ports)

        self._command_code = CommandCode('OPR', modifiers=['LINK', 'FLAP'])
        self._staging_block = StagingBlock(tid=tid, ctag=ctag)
        self._payload = Payload(data_blocks=[data_block, ])
        self._input_message = InputMessage(command_code=self._command_code,
                                           staging_block=self._staging_block,
                                           payload=self._payload)

    @property
    def input_message(self):
        return self._input_message.text


class EntCrsBulk(Command):
    INPUT_FORMAT_SYNTAX = "ENT-CRS-BULK:{tid}:{connList};"

    def __init__(self,
                 session,
                 conn_list,
                 tid=""):
        super(EntCrsBulk, self).__init__(session)

        self._input_message = self.INPUT_FORMAT_SYNTAX.format(tid=tid, connList='&'.join(conn_list))

    @property
    def input_message(self):
        return self._input_message
